<?php
namespace App\Http\Controllers\Operations;use App\Http\Controllers\Controller;use App\Models\{HousekeepingTask,Room,Stay,User};use App\Services\Operations\HousekeepingService;use Illuminate\Http\Request;
class HousekeepingController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('operations.housekeeping.index',['tasks'=>HousekeepingTask::with(['room','assignee'])->where('property_id',$p)->latest()->paginate(50),'rooms'=>Room::where('property_id',$p)->orderBy('room_number')->get(),'staff'=>User::where('property_id',$p)->orderBy('name')->get()]);}public function store(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['room_id'=>'required|integer','type'=>'required|string','priority'=>'required|string','assigned_to'=>'nullable|integer','due_at'=>'nullable|date','notes'=>'nullable|string']);$room=Room::where('property_id',$p)->findOrFail($d['room_id']);HousekeepingTask::create($d+['property_id'=>$p,'status'=>$d['assigned_to']?'assigned':'pending','created_by'=>auth()->id()]);return back()->with('success','Housekeeping task created.');}public function status(Request $r,HousekeepingTask $task,HousekeepingService $service){abort_unless($task->property_id===auth()->user()->property_id,403);$d=$r->validate(['status'=>'required|in:pending,assigned,cleaning,clean,inspected,cancelled','assigned_to'=>'nullable|integer','notes'=>'nullable|string']);$service->setStatus($task,$d['status'],auth()->id(),$d['assigned_to']??null,$d['notes']??null);return back()->with('success','Housekeeping status updated.');}}
